# Compressão de bytes em C++ — Guia prático

Sim, dá para fazer isso. Vou te mostrar uma abordagem **prática e segura** usando duas estratégias:

1. **Compressão real** com `zlib` (deflate) — pequeno mas reversível
2. **Compressão sem dependência externa** usando `std::compressor` do C++11+ (mas ele só comprime *para* outro buffer, não gera array fácil)

Vou usar **zlib** porque é o padrão mais simples para "comprimir → guardar em vetor → decomprimir depois".

---

## 1. Pré-requisitos

Você precisa linkar a biblioteca zlib:

```bash
# Linux (Ubuntu/Debian)
sudo apt install libz-dev

# Windows
baixar https://sourceforge.net/projects/zlib/files/
```

---

## 2. Código completo

### `compressor.cpp`

```cpp
#include <iostream>
#include <vector>
#include <cstring>
#include <zlib.h>
#include <cstdint>

// Estrutura para guardar dados comprimidos
struct CompressedData {
    uint32_t tamanho_original;   // quantos bytes foram originalmente
    uint8_t  *dados_comprimidos; // ponteiro para o buffer zlib
    size_t   tam_comprimido;     // quantos bytes ficaram após compressão
};

// Comprime os dados e aloca um vetor com eles
CompressedData comprimir(const std::vector<uint8_t>& origem) {
    // Buffer temporário para zlib escrever
    unsigned char* tmp = new unsigned char[origem.size() + 1024];
    int ret = deflateInitEx(Z_DEFLASTRAW, &dOut); // veremos abaixo
    // Na prática usamos inflateEnd/compress diretamente
    size_t destSize = origem.size() * 2; // estimativa inicial
    unsigned char* dest = new unsigned char[destSize];

    int comp = compress(dest, &destSize, origem.data(), origem.size());

    if (comp == Z_OK || comp == Z_PARTIAL) {
        // Ajusta o tamanho real
        size_t realTam = destSize;
        // Se sobrou espaço, preenche com zeros
        while (realTam < destSize) ++realTam;

        delete[] tmp;
        return {
            static_cast<uint32_t>(origem.size()),
            dest,
            realTam
        };
    }

    delete[] tmp;
    delete[] dest;
    throw std::runtime_error("Falha na compressão");
}

void liberar(CompressedData& cd) {
    delete[] cd.dados_comprimidos;
    cd.dados_comprimidos = nullptr;
}

// Lê um arquivo .bin que contém: [tamanho_original (4 bytes)] [bytes comprimidos]
bool carregarArquivoComprimido(const std::string& caminho,
                               std::vector<uint8_t>& resultado) {
    FILE* f = fopen(caminho.c_str(), "rb");
    if (!f) throw std::runtime_error("Não abriu arquivo");

    fseek(f, 0, SEEK_END);
    long tamArquivo = ftell(f);
    fseek(f, 0, SEEK_SET);

    // Lê cabeçalho (4 bytes: tamanho original)
    uint32_t orig;
    fread(&orig, 4, 1, f);

    // Lê dados comprimidos
    std::vector<uint8_t> comprimido(orig, orig + tamArquivo);

    fclose(f);

    // Decomprime aqui
    return decomprimir(comprimido, resultado, orig);
}

// Função principal de descompressão
bool decomprimir(const std::vector<uint8�>& buf,
                 std::vector<uint8_t>& resultado,
                 uint32_t tamanhoEsperado) {
    Inflator inflator(buf.data(), buf.size());
    resultado.reserve(tamanhoEsperado);
    while (inflator.OK()) {
        uint8_t b = inflator.next();
        if (!b) break;
        resultado.push_back(b);
    }

    if (static_cast<size_t>(resultado.size()) != tamanhoEsperado) {
        throw std::runtime_error("Tamanho descomprimido não bate");
    }
    return true;
}

// Simples inflador manual (alternativa leve ao zlib para leitura)
class Inflator {
public:
    const uint8_t* data;
    size_t pos = 0;
    bool OK() const { return pos < data.size(); }

    uint8_t next() {
        if (!OK()) return 0;
        uint8_t b = data[pos++];
        // Flato: se LSB for 1, ignora bits até achar LSB=0
        if ((b & 0x80) != 0) {
            while (pos < data.size() && !(data[pos++] & 0x80));
            if (pos >= data.size()) return 0;
            b = data[pos++];
        }
        return b;
    }
};
```

