## 4. `main.cpp` — exemplo de uso

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <zlib.h>
#include <cstdint>
#include <cstdlib>

struct CompressedData {
    uint32_t tamanho_original;
    uint8_t* dados_comprimidos;
    size_t tam_comprimido;
};

CompressedData comprimir(const std::vector<uint8_t>& dados) {
    unsigned char* tmp = new unsigned char[dados.size() + 1024];
    unsigned char* out = new unsigned char[dados.size() * 2];
    size_t outLen = dados.size() * 2;

    int r = compress(out, &outLen, dados.data(), dados.size());
    if (r != Z_OK && r != Z_PARTIAL) {
        delete[] tmp; delete[] out;
        throw std::runtime_error("Compressão falhou");
    }

    // Trim final
    while (outLen > dados.size()) --outLen;
    // Garantir alinhamento múltiplo de 8 (padrão zlib)
    while (outLen % 8 != 0) ++outLen;

    delete[] tmp;
    return {static_cast<uint32_t>(dados.size()), out, outLen};
}

int main(int argc, char* argv[]) {
    // --- PASSO 1: Ler dados originais ---
    std::ifstream in("dados_orig.bin", std::ios::binary);
    if (!in) { std::cerr << "Use 'dados_orig.bin' como entrada\n"; return 1; }

    std::vector<uint8_t> raw((std::istreambuf_iterator<char>(in)),
                             std::istreambuf_iterator<char>());

    // --- PASSO 2: Comprimir ---
    CompressedData cd = comprimir(raw);

    // --- PASSO 3: Escrever arquivo comprimido no formato customizado ---
    // Formato: [4 bytes U32 tamanho_original][N bytes dados]
    FILE* f = fopen("dados_comprimido.bin", "wb");
    if (!f) { std::cerr << "Falha ao salvar\n"; return 1; }

    fwrite(&cd.tamanho_original, 4, 1, f);
    fwrite(cd.dados_comprimidos, 1, cd.tam_comprimido, f);
    fclose(f);
    delete[] cd.dados_comprimidos;

    std::cout << "Original: " << raw.size() << " bytes"
              << "\nComprimido: " << cd.tam_comprimido << " bytes"
              << "\nEconomia: "
              << ((100.0 - 100.0 * static_cast<double>(cd.tam_comprimido) /
                            static_cast<double>(raw.size())))
              << "%" << std::endl;

    // --- PASSO 4: Função de leitura dos bytes comprimidos ---
    auto lerComprimido = [&](const std::string& caminho,
                             std::vector<uint8_t>& resultado) -> bool {
        std::ifstream file(caminho, std::ios::binary);
        if (!file) return false;

        uint8_t header[4];
        file.read(header, 4);
        uint32_t esperado = *reinterpret_cast<const uint32_t*>(header);

        std::vector<uint8_t> bruto(esperado + 4);
        size_t pos = 4;
        file.read(bruto.data() + pos, bruto.size() - pos);

        // Descomprime
        unsigned char* out = new unsigned char[bruto.size() * 4];
        int len = 0;
        int r = uncompress(out, &len, bruto.data(), bruto.size() - 4);
        if (r != Z_OK) { delete[] out; return false; }

        len = static_cast<size_t>(r);
        resultado.assign(out, len);
        delete[] out;
        return true;
    };

    // --- PASSO 5: Usar na leitura ---
    std::vector<uint8_t> recuperados;
    if (!lerComprimido("dados_comprimido.bin", recuperados))
        return 1;

    // Comparar
    if (raw == recuperados) {
        std::cout << "✓ Dados recuperados com sucesso!\n";
    } else {
        std::cerr << "✗ Divergência nos dados!\n";
        return 1;
    }

    return 0;
}
```

